    terme = 5
    for k in range(n):
        terme = 2 * terme - 3
    return terme

def u(n):
    return 3 * n + 2

def somme(n):
    total = 0
    for k in range(n + 1):
        total = total + u(k)
    return total

def f(x):
    return x * x - 2

def racine(eps):
    a = 1
    b = 2
    while b - a > eps:
        m = (a + b) / 2
        if f(m) < 0:
            a = m
        else:
            b = m
    return (a + b) / 2

def euler(n):
    h = 1 / n
    y = 1
    for k in range(n):
        y = y + h * y
    return y

def population(n):
    p = 200
    for k in range(n):
        p = 1.05 * p - 4
    return p

def annee_seuil(S):
    p = 200
    n = 0
    while p <= S:
        p = 1.05 * p - 4
        n = n + 1
    return n

def total_cumule(n):
    total = 0
    for k in range(n + 1):
        total = total + population(k)
    return total
